package android.graphics; public class RectF {public float left,top,right,bottom;public RectF(float l,float t,float r,float b){left=l;top=t;right=r;bottom=b;}public RectF(RectF r){this(r.left,r.top,r.right,r.bottom);}public float width(){return right-left;}public float height(){return bottom-top;}public float centerX(){return(left+right)/2;}public float centerY(){return(top+bottom)/2;}public boolean contains(float x,float y){return x>=left&&x<right&&y>=top&&y<bottom;}@Override public boolean equals(Object other){if(!(other instanceof RectF))return false;RectF r=(RectF)other;return left==r.left&&top==r.top&&right==r.right&&bottom==r.bottom;}@Override public int hashCode(){return Float.floatToIntBits(left);}}
